from dataclasses import dataclass
from functools import lru_cache
from pathlib import Path

from .errors import PlaceNotFound

log = logging.getLogger(__name__)

DATA = Path(__file__).parent / "data" / "landmarks.csv"
_SEP = re.compile(r"[\W_]+")


@dataclass(frozen=True)
class Place:
    name: str
    kind: str
    lat: float
    lon: float
    aliases: tuple[str, ...] = ()


def normalize(name: str) -> str:
    """Lowercase, and collapse punctuation, underscores and whitespace to single spaces."""
    return _SEP.sub(" ", name).strip().casefold()


def _in_range(lat: float, lon: float) -> bool:
    return -90.0 <= lat <= 90.0 and -180.0 <= lon <= 180.0


def load(path: Path | str = DATA) -> dict[str, Place]:
    """Index of normalized name and alias -> Place. Rows with out-of-range coordinates are skipped."""
    index: dict[str, Place] = {}
    with open(path, newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            lat, lon = float(row["lat"]), float(row["lon"])
            if not _in_range(lat, lon):
                log.debug("skipping %r: coordinates out of range (%s, %s)", row["name"], lat, lon)
                continue
            aliases = tuple(a.strip() for a in row["aliases"].split(";") if a.strip())
            place = Place(row["name"], row["kind"], lat, lon, aliases)
            for key in (row["name"], *aliases):
                index.setdefault(normalize(key), place)
    return index


@lru_cache(maxsize=1)
def _default_index() -> dict[str, Place]:
    return load()


def resolve(name: str) -> Place:
    """The place whose name or alias matches `name`."""
    try:
        return _default_index()[normalize(name)]
    except KeyError:
        raise PlaceNotFound(f"no place matching {name!r}") from None

import pytest

from placeindex import PlaceNotFound, normalize, resolve


def close(place, lat, lon, tol=0.01):
    return abs(place.lat - lat) < tol and abs(place.lon - lon) < tol


def test_normalize():
    assert normalize("  Tour  Eiffel ") == "tour eiffel"
    assert normalize("Ponte_Vecchio") == "ponte vecchio"
    assert normalize("San Francisco-Oakland") == "san francisco oakland"


def test_resolve_eiffel_tower():
    assert close(resolve("Eiffel Tower"), 48.8584, 2.2945)


def test_resolve_by_alias():
    assert resolve("Big Ben").name == "Elizabeth Tower"
    assert resolve("cristo redentor").name == "Christ the Redeemer"


def test_resolve_brooklyn_bridge():
    assert close(resolve("Brooklyn Bridge"), 40.7061, -73.9969)


def test_resolve_bay_bridge():
    assert close(resolve("Bay Bridge"), 37.7983, -122.3778)


def test_resolve_golden_gate_bridge():
    place = resolve("Golden Gate Bridge")
    assert place.kind == "bridge"
    assert close(place, 37.8199, -122.4783)


def test_resolve_southern_hemisphere():
    assert close(resolve("Sydney Opera House"), -33.8568, 151.2153)


def test_unknown_place():
    with pytest.raises(PlaceNotFound):
        resolve("Atlantis")

"""Gazetteer loading and name lookup."""

